import { isEqual } from 'lodash-es';
import { useRef, useState } from 'react';

/**
 * Hook that checks if the initially loaded fonts were updated.
 * Used to trigger remeasuring in the DataTable (autoWidth) and TextEllipsis once all fonts are loaded.
 *
 * @param callback - optionally pass a function to be executed once when the fonts were updated
 * @returns boolean whether the fonts have changed
 * @internal
 */
export function _useFontsUpdated(callback?: () => void): boolean {
  const [fontsUpdated, setFontsUpdated] = useState(false);
  const prevFontFamilies = useRef<string[]>();
  const fontFamilies: string[] = [];
  const firstRender = useRef(true);

  if (document.fonts) {
    // gather the font families that are already loaded
    if (firstRender.current) {
      const loadedFontFamilies: string[] = [];
      document.fonts.forEach((fontFace: FontFace) =>
        loadedFontFamilies.push(`${fontFace.family} ${fontFace.weight}`),
      );
      prevFontFamilies.current = loadedFontFamilies;
      firstRender.current = false;
    }

    document.fonts.ready.then((fontFaceSet: FontFaceSet) => {
      fontFaceSet.forEach((fontFace: FontFace) =>
        fontFamilies.push(`${fontFace.family} ${fontFace.weight}`),
      );

      if (!isEqual(prevFontFamilies.current, fontFamilies)) {
        prevFontFamilies.current = fontFamilies;
        callback?.();
        setFontsUpdated(true);
      }
    });
  }

  return fontsUpdated;
}
